code.source:
#include <stdio.h>

int main(void) {
    int hasTicket, age;

    printf("Do you have a ticket? (1 = yes, 0 = no): ");
    scanf("%d", &hasTicket);

    if (hasTicket == 1) {
        printf("Enter your age: ");
        scanf("%d", &age);

        if (age >= 18) {
            printf("Welcome to the beach concert!\n");
        } else {
            printf("Sorry, adults only tonight.\n");
        }
    } else {
        printf("No ticket, no entry.\n");
    }

    return 0;
}

